import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"Agent 系统组导览","description":"从单次动作到自治闭环：心智模型、设计模式、状态与恢复、控制面与规模化的十页导航。","frontmatter":{"title":"Agent 系统组导览","description":"从单次动作到自治闭环：心智模型、设计模式、状态与恢复、控制面与规模化的十页导航。","domain":"tech","tags":["tech","agent-systems","navigation"],"navOrder":59,"topicId":"agent-systems-guide","layer":"6","status":"canonical","nodeType":"problem","owner":"learn-ai","externalOwners":[],"prerequisites":["tool-execution"],"next":["agent-runtime","workflow","recovery-hitl"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/06-agent-systems/index.md","filePath":"zh/tech/06-agent-systems/index.md","lastUpdated":1791165915000}'),o={name:"zh/tech/06-agent-systems/index.md"};function d(i,t,s,l,h,g){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="agent-系统组导览" tabindex="-1">Agent 系统组导览 <a class="header-anchor" href="#agent-系统组导览" aria-label="Permalink to &quot;Agent 系统组导览&quot;">​</a></h1><blockquote><p><strong>所在组</strong>：Agent 系统 ｜ <strong>上一组出口</strong>：能定义并安全执行一次受控动作 ｜ <strong>本组出口</strong>：能搭建一个有状态、可恢复、权限受限的自治循环</p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>结论先讲</strong>：本组把「单次动作」升级为「持续闭环」：模型在一个循环里观察、决策、行动，直到触发停止条件。闭环带来自治，也带来新的失败维度——状态膨胀、死循环、错误传播、无人监督的副作用。组内十页按「先心智模型、再模式、再控制面、最后规模化」排列。</p><table tabindex="0"><thead><tr><th>顺序</th><th>页面</th><th>回答的问题</th></tr></thead><tbody><tr><td>前门</td><td><a href="./agent-runtime.html">心智模型与运行时</a></td><td>闭环由什么组成？何时值得上 agent？</td></tr><tr><td>模式</td><td><a href="./design-patterns.html">设计模式</a></td><td>ReAct、路由、规划-执行、反思如何选？</td></tr><tr><td>状态</td><td><a href="./state-memory.html">状态与记忆</a></td><td>跨步/跨轮的数据放哪、怎么恢复？</td></tr><tr><td>控制面</td><td><a href="./hooks.html">Hooks</a></td><td>生命周期拦截与自动化策略门</td></tr><tr><td>控制面</td><td><a href="./recovery-hitl.html">恢复与人工批准</a></td><td>失败后回到哪个状态？何时必须等人？</td></tr><tr><td>环境适配</td><td><a href="./computer-use.html">Computer Use</a></td><td>只有视觉 UI 可用时如何 observe→act→verify</td></tr><tr><td>确定性替代</td><td><a href="./workflow.html">工作流模式</a></td><td>什么时候<strong>不要</strong>用 agent</td></tr><tr><td>能力包装</td><td><a href="./skills.html">Skills</a> · <a href="./plugins.html">Plugins</a></td><td>程序性知识与能力包的分发</td></tr><tr><td>规模化</td><td><a href="./multi-agent.html">子代理 / 多 Agent</a></td><td>同信任域内的委派与编排</td></tr></tbody></table><p><strong>边界</strong>：跨进程 / 组织 / 信任域的委派不属于本组——先过 <a href="./../07-interoperability/">互操作组</a>（A2A 等）。</p><h2 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to &quot;2. 使用&quot;">​</a></h2><ul><li>第一次接触 agent：按上表从 <a href="./agent-runtime.html">心智模型与运行时</a> 顺序读。</li><li>已在生产跑 agent：直接跳 <a href="./recovery-hitl.html">恢复与人工批准</a> 与 <a href="./hooks.html">Hooks</a>。</li><li>不确定该不该用 agent：先读 <a href="./workflow.html">工作流模式</a> 的反向决策。</li></ul><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><p>闭环的三个不变量：<strong>停止条件必须显式</strong>（步数 / token / 时间三轴预算）、<strong>状态必须可检查点</strong>、<strong>副作用必须经过行动组的执行纪律</strong>。缺任何一条，自治只会放大失败。</p><h2 id="_4-开发" tabindex="-1">4. 开发 <a class="header-anchor" href="#_4-开发" aria-label="Permalink to &quot;4. 开发&quot;">​</a></h2><p>各组员的开发段共用同一套调试口径：症状 → 证据（trace/checkpoint）→ 处理 → 完成标准。多 agent 的调试单位是委派；单 agent 的调试单位是循环步。</p><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><p>各主题页自带四级阅读路线；组级入口推荐 Anthropic《Building Effective Agents》与 OpenAI Agents 指南（见 agent-runtime 资料库表）。</p>',14)])])}const _=e(o,[["render",d]]);export{u as __pageData,_ as default};
